#include <torch/extension.h>
#include <cuda_runtime.h>

// optimized kernel using shared memory
__global__ void matrix_multiply_kernel_optimized(const float* A, const float* B, float* C, int N) {
    // Tile size, often a multiple of warp size (32)
    // A common choice is 16, 32 or 64. Let's start with 32 for better parallelism.
    const int TILE_SIZE = 32;

    // Shared memory for tiles of A and B
    // __shared__ specifies that these arrays reside in shared memory
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Calculate the row and column of the C matrix element that this thread is responsible for
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    // Each block processes a C_TILE_SIZExC_TILE_SIZE tile of the C matrix.
    // To compute one element C[row][col], we need to sum products of A[row][k] * B[k][col].
    // This loop iterates through the 'k' dimension in chunks of TILE_SIZE.
    for (int tile_k = 0; tile_k < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile_k) {

        // Load tile from global memory to shared memory
        // Each thread loads one element of the tile
        // A tile of A: As[threadIdx.y][threadIdx.x] = A[row][tile_k * TILE_SIZE + threadIdx.x]
        if (row < N && (tile_k * TILE_SIZE + threadIdx.x) < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + (tile_k * TILE_SIZE + threadIdx.x)];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // B tile: Bs[threadIdx.y][threadIdx.x] = B[tile_k * TILE_SIZE + threadIdx.y][col]
        if ((tile_k * TILE_SIZE + threadIdx.y) < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[(tile_k * TILE_SIZE + threadIdx.y) * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // Synchronize threads to ensure all data is loaded into shared memory
        __syncthreads();

        // Perform the dot product for the current tile
        // Each thread calculates one element of the C tile based on the shared A and B tiles
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        // Synchronize threads again before loading the next tile
        __syncthreads();
    }

    // Write the final result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int TILE_SIZE = 32; // Must match the TILE_SIZE in the kernel

    // Grid dimensions based on N and TILE_SIZE
    int grid_dim_x = (N + TILE_SIZE - 1) / TILE_SIZE;
    int grid_dim_y = (N + TILE_SIZE - 1) / TILE_SIZE;
    dim3 grid_dim(grid_dim_x, grid_dim_y);

    // Block dimensions are TILE_SIZExTILE_SIZE
    dim3 block_dim(TILE_SIZE, TILE_SIZE);

    matrix_multiply_kernel_optimized<<<grid_dim, block_dim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);
    cudaDeviceSynchronize();

    return C;
}
"""

