__global__ void matrix_multiply_kernel_optimized_bank_conflict(const float* A, const float* B, float* C, int N) {
    const int TILE_SIZE = 32;
    const int TILE_SIZE_PLUS_ONE = TILE_SIZE + 1; // Used for padding to avoid bank conflicts

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE_PLUS_ONE]; // Padded to avoid bank conflicts

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile_k = 0; tile_k < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile_k) {
        // Load tile from global memory to shared memory
        // As (row-major access in global memory, column-major access in shared memory within tile calculation)
        if (row < N && (tile_k * TILE_SIZE + threadIdx.x) < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + (tile_k * TILE_SIZE + threadIdx.x)];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        // Bs (column-major access in global memory, row-major access in shared memory within tile calculation)
        // Padded access for Bs to avoid bank conflicts on subsequent accesses in the inner loop.
        if ((tile_k * TILE_SIZE + threadIdx.y) < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[(tile_k * TILE_SIZE + threadIdx.y) * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads();

        // Perform the dot product for the current tile
        // Accessing As[threadIdx.y][k] and Bs[k][threadIdx.x]
        // For Bs, the stride in k (column access in shared memory) could cause bank conflicts if TILE_SIZE is a multiple of 32
        // Padding with TILE_SIZE_PLUS_ONE helps avoid this.
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
